-- Exact rollback of CPF oracle initial baseline for refDB
BEGIN EXECUTE IMMEDIATE 'DROP TABLE ref_sample_item CASCADE CONSTRAINTS PURGE'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF; END;
/
